import { useEffect, useState } from "react";
import API from "../services/api";
import UnifiedNavbar from "../components/UnifiedNavbar";

function Attendance(){

  const [userRole, setUserRole] = useState("student");
  const [students, setStudents] = useState([]);
  const [attendance, setAttendance] = useState([]);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [markingAttendanceId, setMarkingAttendanceId] = useState(null);

  useEffect(() => {
    const storedUser = localStorage.getItem("user");
    if (storedUser) {
      try {
        const user = JSON.parse(storedUser);
        setUserRole(user.role ? user.role.toLowerCase() : "student");
      } catch (e) {
        setUserRole("student");
      }
    }
  }, []);

  useEffect(() => {
    if (userRole === "admin" || userRole === "staff") {
      fetchStudentsAndAttendance();
    }
  }, [selectedDate, userRole]);

  const fetchStudentsAndAttendance = async () => {
    try {
      setLoading(true);
      const studentsRes = await API.get("/student");
      setStudents(studentsRes.data || []);

      const attendanceRes = await API.get("/attendance", {
        params: { date: selectedDate }
      });
      setAttendance(attendanceRes.data || []);
    } catch (error) {
      console.log("Error fetching data:", error);
      setMessage("Error loading data");
      setTimeout(() => setMessage(""), 3000);
    } finally {
      setLoading(false);
    }
  };

  const markAttendance = async (studentId, status) => {
    try {
      setMarkingAttendanceId(studentId);
      const existingRecord = attendance.find(a => a.studentId === studentId);
      
      const attendanceData = {
        studentId: studentId,
        date: selectedDate,
        status: status,
        mealType: "Breakfast & Lunch"
      };

      console.log("Marking attendance:", attendanceData);
      
      let response;
      if (existingRecord) {
        console.log("Updating attendance record:", existingRecord.id);
        response = await API.put(`/attendance/${existingRecord.id}`, attendanceData);
      } else {
        console.log("Creating new attendance record");
        response = await API.post("/attendance", attendanceData);
      }

      console.log("Attendance marked successfully:", response.data);
      setMessage(`✓ Attendance marked as ${status}`);
      setTimeout(() => setMessage(""), 2000);
      
      // Refresh data
      await fetchStudentsAndAttendance();
    } catch (error) {
      console.error("Full error object:", error);
      console.error("Error response:", error.response?.data);
      console.error("Error status:", error.response?.status);
      console.error("Error message:", error.message);
      
      const errorMsg = error.response?.data?.message || error.message || "Unknown error";
      setMessage(`✗ Error: ${errorMsg}`);
      setTimeout(() => setMessage(""), 4000);
    } finally {
      setMarkingAttendanceId(null);
    }
  };

  const getStudentAttendanceStatus = (studentId) => {
    const record = attendance.find(a => a.studentId === studentId);
    return record ? record.status : null;
  };

  const getAttendanceStats = () => {
    const present = attendance.filter(a => a.status === "Present").length;
    const absent = attendance.filter(a => a.status === "Absent").length;
    const leave = attendance.filter(a => a.status === "Leave").length;
    return { present, absent, leave };
  };

  const stats = getAttendanceStats();

return(

<div className="dashboard">

<UnifiedNavbar />

<div className="main-content">

<h1>Attendance Management</h1>

    {message && (
      <div className={`message ${message.includes("✓") ? "success" : "error"}`}>
        {message}
      </div>
    )}

{(userRole === "admin" || userRole === "staff") ? (
  <>
    <div className="attendance-controls">
      <label>Select Date: </label>
      <input 
        type="date" 
        value={selectedDate} 
        onChange={(e) => setSelectedDate(e.target.value)}
      />
    </div>

    <div className="attendance-stats">
      <div className="stat-card">
        <span className="stat-label">Present</span>
        <span className="stat-value present">{stats.present}</span>
      </div>
      <div className="stat-card">
        <span className="stat-label">Absent</span>
        <span className="stat-value absent">{stats.absent}</span>
      </div>
      <div className="stat-card">
        <span className="stat-label">Leave</span>
        <span className="stat-value leave">{stats.leave}</span>
      </div>
    </div>

    <div className="attendance-table-container">
      {loading ? (
        <p>Loading...</p>
      ) : (
        <table className="table">
          <thead>
            <tr>
              <th>Student ID</th>
              <th>Student Name</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {students.map(student => (
              <tr key={student.id}>
                <td>{student.id}</td>
                <td>{student.name}</td>
                <td>
                  <span className={`status-badge ${getStudentAttendanceStatus(student.id)?.toLowerCase() || "unmarked"}`}>
                    {getStudentAttendanceStatus(student.id) || "Not Marked"}
                  </span>
                </td>
                <td>
                  <div className="action-buttons">
                    <button 
                      className={`btn-sm present ${getStudentAttendanceStatus(student.id) === "Present" ? "active" : ""}`}
                      onClick={() => markAttendance(student.id, "Present")}
                      disabled={markingAttendanceId === student.id}
                      title="Mark Present"
                    >
                      {markingAttendanceId === student.id ? "..." : "✓"}
                    </button>
                    <button 
                      className={`btn-sm absent ${getStudentAttendanceStatus(student.id) === "Absent" ? "active" : ""}`}
                      onClick={() => markAttendance(student.id, "Absent")}
                      disabled={markingAttendanceId === student.id}
                      title="Mark Absent"
                    >
                      {markingAttendanceId === student.id ? "..." : "✗"}
                    </button>
                    <button 
                      className={`btn-sm leave ${getStudentAttendanceStatus(student.id) === "Leave" ? "active" : ""}`}
                      onClick={() => markAttendance(student.id, "Leave")}
                      disabled={markingAttendanceId === student.id}
                      title="Mark Leave"
                    >
                      {markingAttendanceId === student.id ? "..." : "📋"}
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  </>
) : (
  <p>Attendance system is being managed. Go to your dashboard to mark your attendance.</p>
)}

</div>

</div>

)

}

export default Attendance
